import manifest from '../assets/backgrounds/backgrounds.json';

/**
 * The print the empty state opens on: its file name in backgrounds/, e.g.
 * 'riso-print-2026-11-04-13-12-16.png' (the extension is optional). null
 * opens on a random one each visit.
 */
const DEFAULT_BACKGROUND: string | null = "riso-print-2026-11-04-13-15-02.png";

// Generated by `npm run backgrounds` from the prints in backgrounds/.
const urls = import.meta.glob<string>('../assets/backgrounds/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
});

export interface BackgroundCrop {
  url: string;
  width: number;
  height: number;
}

export interface Background {
  name: string;
  /** For the stacked (phone) layout. */
  portrait: BackgroundCrop;
  /** For the side-by-side layout. */
  landscape: BackgroundCrop;
}

const crop = ({ file, width, height }: (typeof manifest)[number]['portrait']): BackgroundCrop => ({
  url: urls[`../assets/backgrounds/${file}`],
  width,
  height,
});

export const BACKGROUNDS: Background[] = manifest.map((b) => ({
  name: b.name,
  portrait: crop(b.portrait),
  landscape: crop(b.landscape),
}));

/** Where the gallery starts: the default print, or a random one. */
export function firstBackgroundIndex(): number {
  // Names are file names without their extension (see scripts/backgrounds.mjs).
  const wanted = DEFAULT_BACKGROUND?.replace(/\.[^.]+$/, '');
  const index = BACKGROUNDS.findIndex((b) => b.name === DEFAULT_BACKGROUND || b.name === wanted);
  if (DEFAULT_BACKGROUND !== null && index < 0) {
    console.warn(`No background named "${DEFAULT_BACKGROUND}" in backgrounds/; picking one at random.`);
  }
  return index >= 0 ? index : Math.floor(Math.random() * BACKGROUNDS.length);
}
